/* PipSePaisa V179 — Company Finance Management System */
(function(){
'use strict';
if(window.__PSP_FINANCE_V179__)return;window.__PSP_FINANCE_V179__=true;
const F={tab:'dashboard',month:new Date().toISOString().slice(0,7),data:{tx:[],accounts:[],balances:[],staff:[],salary:[],partners:[],payouts:[],obligations:[],recurring:[],budgets:[],closures:[],audit:[],adminLogs:[]},charts:{},loading:false,filters:{q:'',type:'all',status:'all',category:'all'},_loaded:false,_loadPromise:null,_lastRenderKey:'',_lastLoadAt:0,_preparedMonth:'',_mounted:false};
const C=['#20b373','#ff4c57','#347df5','#fb9201','#8a48dc','#19b6ad','#f0b42b','#8394a9'];
function db(){try{if(typeof sb!=='undefined'&&sb)return sb;if(window.sb)return window.sb}catch(_){return null}}
function q(s,r){return (r||document).querySelector(s)}function qa(s,r){return Array.from((r||document).querySelectorAll(s))}
function esc(v){return String(v==null?'':v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function n(v){v=Number(v);return Number.isFinite(v)?v:0}function money(v,c='USD'){const x=n(v);return (String(c||'USD').toUpperCase()==='USD'?'$':String(c)+' ')+x.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}
function monthStart(k=F.month){return k+'-01'}function monthEnd(k=F.month){const p=k.split('-').map(Number),d=new Date(p[0],p[1],1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-01'}
function monthLabel(k=F.month){const p=k.split('-').map(Number);return new Date(p[0],p[1]-1,1).toLocaleDateString(undefined,{month:'long',year:'numeric'})}
function monthShort(k){const p=k.split('-').map(Number);return new Date(p[0],p[1]-1,1).toLocaleDateString(undefined,{month:'short'})}
function months(count=12){const p=F.month.split('-').map(Number),out=[];for(let i=count-1;i>=0;i--){const d=new Date(p[0],p[1]-1-i,1);out.push(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'))}return out}
function dt(v){if(!v)return'—';try{return new Date(v).toLocaleString()}catch(_){return String(v)}}function date(v){if(!v)return'—';try{return new Date(v+'T00:00:00').toLocaleDateString()}catch(_){return v}}
function toast(m,t){if(window.pipToast)return pipToast(m,t==='error'?'err':'ok');alert(m)}
async function confirmX(m){return typeof window.pspConfirm==='function'?window.pspConfirm(m):confirm(m)}
async function audit(action,summary,target,id,oldv,newv){try{await window.pspAuditLog?.({action,section:'revenue',target_type:target||'finance',target_id:id||null,summary,old_value:oldv||null,new_value:newv||null})}catch(_){}}
function curAdminId(){try{return currentAdmin?.id||null}catch(_){return null}}
function currentMonth(){return new Date().toISOString().slice(0,7)}
function statusPill(v){v=String(v||'').toLowerCase();let c=/paid|approved|received/.test(v)?'green':/reject|cancel/.test(v)?'red':/pending_approval|pending|partial/.test(v)?'orange':'gray';return `<span class="f179-pill ${c}">${esc(v.replace(/_/g,' ')||'—')}</span>`}
function typePill(r){let c=r.direction==='credit'?'green':'red';return `<span class="f179-pill ${c}">${esc(r.transaction_type||'')}</span>`}
function isPaid(r){return ['paid','approved'].includes(String(r.status||'').toLowerCase())}
function txForMonth(k=F.month){return F.data.tx.filter(r=>String(r.period_month||'').slice(0,7)===k&& !['cancelled','rejected'].includes(String(r.status||'').toLowerCase()))}
function monthSalary(k=F.month){return F.data.salary.filter(r=>String(r.period_month||'').slice(0,7)===k&&r.status!=='cancelled')}
function monthPayout(k=F.month){return F.data.payouts.filter(r=>String(r.period_month||'').slice(0,7)===k&&r.status!=='cancelled')}
function summary(k=F.month){const tx=txForMonth(k),sal=monthSalary(k),po=monthPayout(k);let income=0,op=0,paidSalary=0,paidPartner=0;tx.forEach(r=>{if(!isPaid(r))return;if(r.direction==='credit')income+=n(r.amount);else if(r.transaction_type==='salary')paidSalary+=n(r.amount);else if(r.transaction_type==='partner_payout')paidPartner+=n(r.amount);else op+=n(r.amount)});const salaryDue=sal.reduce((s,r)=>s+n(r.payable_amount),0),partnerDue=po.reduce((s,r)=>s+n(r.amount_due),0);const salaries=Math.max(salaryDue,paidSalary),partners=Math.max(partnerDue,paidPartner);const obligations=F.data.obligations.filter(o=>String(o.obligation_type)==='payable'&&!['paid','cancelled'].includes(String(o.status))).reduce((s,o)=>s+n(o.amount),0);const pendingTx=tx.filter(r=>r.direction==='debit'&&['pending','pending_approval'].includes(r.status)).reduce((s,r)=>s+n(r.amount),0);const pendingSalary=sal.reduce((s,r)=>s+Math.max(0,n(r.payable_amount)-(r.status==='paid'?n(r.payable_amount):0)),0);const pendingPartner=po.reduce((s,r)=>s+Math.max(0,n(r.amount_due)-n(r.amount_paid)),0);const pending=obligations+pendingTx+pendingSalary+pendingPartner;const net=income-op-salaries-partners,margin=income>0?net/income*100:0;return{income,op,salaries,partners,net,margin,pending,txCount:tx.length}}
function incomeMap(k=F.month){const m={};txForMonth(k).filter(r=>r.direction==='credit'&&isPaid(r)).forEach(r=>m[r.category]=(m[r.category]||0)+n(r.amount));return m}
function expenseMap(k=F.month){const m={};txForMonth(k).filter(r=>r.direction==='debit'&&isPaid(r)&&r.transaction_type==='expense').forEach(r=>m[r.category]=(m[r.category]||0)+n(r.amount));return m}
function approvedCourseRevenue(k=F.month){return txForMonth(k).filter(r=>r.direction==='credit'&&isPaid(r)&&(r.category==='Paid Course Revenue'||String(r.source_ref||'').startsWith('COURSE:'))).reduce((s,r)=>s+n(r.amount),0)}
function closed(){return F.data.closures.some(r=>String(r.period_month||'').slice(0,7)===F.month)}
function byId(arr,id){return arr.find(x=>String(x.id)===String(id))}

function mount(){const page=q('#page-revenue');if(!page)return;document.body.classList.remove('finance-ref-mode','finance-dashboard-view','v174-simple-revenue','v174-show-advanced');page.innerHTML=`<div class="f179" id="f179Root"><div class="f179-loading">Loading Finance & Accounts…</div></div><div class="f179-modal" id="f179Modal" onclick="if(event.target===this)pspF179CloseModal()"><div class="f179-modal-card" id="f179ModalCard"></div></div>`;}
function header(){const s=summary(),cl=closed();return `<div class="f179-head"><div class="f179-titlebox"><div class="eye">Finance Control Center</div><h2>💼 Finance & Accounts</h2><p>Track company income, expenses, salaries, partner payouts and real profit in one place.</p></div><div class="f179-period"><input type="month" id="f179Month" value="${F.month}" onchange="pspF179Month(this.value)"><span class="f179-closed ${cl?'':'f179-open'}">${cl?'🔒 CLOSED':'● OPEN'}</span>${!cl?`<button class="f179-btn" onclick="pspF179CloseMonth()">🔒 Close Month</button>`:`<button class="f179-btn" onclick="pspF179OpenTxn(null,'adjustment')">＋ Adjustment</button>`}<button class="f179-add" onclick="pspF179OpenTxn()">＋ Add Transaction</button></div></div>${alertsHtml()}${tabsHtml()}`}
function tabsHtml(){const tabs=[['dashboard','📊 Dashboard'],['transactions','💳 Transactions'],['income','💰 Income & Expenses'],['staff','👥 Staff & Salary'],['partners','🤝 Partner Payouts'],['accounts','🏦 Accounts'],['reports','📄 Reports & Audit']];return `<div class="f179-tabs">${tabs.map(([k,l])=>`<button class="f179-tab ${F.tab===k?'active':''}" onclick="pspF179Tab('${k}')">${l}</button>`).join('')}</div>`}
function alertsHtml(){const now=new Date(),ap=F.data.tx.filter(r=>r.status==='pending_approval').length,os=F.data.obligations.filter(o=>o.status==='pending'&&o.due_date&&new Date(o.due_date+'T23:59:59')<now).length,ss=monthSalary().filter(r=>r.status!=='paid'&&r.due_date&&new Date(r.due_date+'T23:59:59')<now).length,bads=budgetState().filter(b=>b.pct>=b.warning).length;const a=[];if(ap)a.push(`<span class="f179-alert warn">⚠ ${ap} expense approval${ap>1?'s':''} waiting</span>`);if(os)a.push(`<span class="f179-alert bad">⏰ ${os} overdue payable/receivable</span>`);if(ss)a.push(`<span class="f179-alert bad">💼 ${ss} overdue salary payment${ss>1?'s':''}</span>`);if(bads)a.push(`<span class="f179-alert warn">📊 ${bads} budget warning${bads>1?'s':''}</span>`);if(!a.length)a.push(`<span class="f179-alert ok">✓ Finance checks are clear for ${esc(monthLabel())}</span>`);return `<div class="f179-alerts">${a.join('')}</div>`}
function kpis(){const s=summary(),prev=summary(prevMonth(F.month));function meta(v,p,invert){if(!p)return esc(monthLabel());const d=(v-p)/Math.abs(p)*100,good=invert?d<=0:d>=0;return `<em class="${good?'good':'bad'}">${d>=0?'↑':'↓'} ${Math.abs(d).toFixed(1)}% vs previous month</em>`}return `<div class="f179-kpis"><div class="f179-kpi" style="--accent:#20b373"><div class="f179-kpi-ico">↑</div><small>Total Income</small><strong>${money(s.income)}</strong>${meta(s.income,prev.income)}</div><div class="f179-kpi" style="--accent:#ff4c57"><div class="f179-kpi-ico">▣</div><small>Operating Expenses</small><strong>${money(s.op)}</strong>${meta(s.op,prev.op,true)}</div><div class="f179-kpi" style="--accent:#347df5"><div class="f179-kpi-ico">♟</div><small>Staff Salaries</small><strong>${money(s.salaries)}</strong>${meta(s.salaries,prev.salaries,true)}</div><div class="f179-kpi" style="--accent:#ff7900"><div class="f179-kpi-ico">◇</div><small>Net Profit</small><strong>${money(s.net)}</strong>${meta(s.net,prev.net)}</div><div class="f179-kpi" style="--accent:#ffae21"><div class="f179-kpi-ico">%</div><small>Profit Margin</small><strong>${s.margin.toFixed(2)}%</strong><em>Net profit / income</em></div><div class="f179-kpi" style="--accent:#8a48dc"><div class="f179-kpi-ico">◆</div><small>Pending Payables</small><strong>${money(s.pending)}</strong><em>Outstanding company obligations</em></div></div>`}
function prevMonth(k){const p=k.split('-').map(Number),d=new Date(p[0],p[1]-2,1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')}
function legend(m){const arr=Object.entries(m).sort((a,b)=>b[1]-a[1]);return arr.length?arr.slice(0,6).map(([k,v],i)=>`<div class="f179-leg"><i style="background:${C[i%C.length]}"></i><div><b>${esc(k)}</b><small>${money(v)}</small></div></div>`).join(''):`<div class="f179-empty">No data</div>`}
function recentRows(){const rs=txForMonth().slice().sort((a,b)=>new Date(b.transaction_date)-new Date(a.transaction_date)||new Date(b.created_at)-new Date(a.created_at)).slice(0,7);return rs.length?rs.map(r=>`<tr><td>${esc(r.transaction_date)}</td><td>${typePill(r)}</td><td><strong>${esc(r.category)}</strong><div style="font-size:6.5px;color:var(--f-muted)">${esc(r.description||r.subcategory||'')}</div></td><td class="f179-money ${r.direction==='credit'?'plus':'minus'}">${r.direction==='credit'?'+':'-'}${money(r.amount)}</td><td>${statusPill(r.status)}</td></tr>`).join(''):`<tr><td colspan="5" class="f179-empty">No transactions this month.</td></tr>`}
function quickActions(){return `<div class="f179-actions"><button class="f179-action" onclick="pspF179OpenTxn()"><i>⚙</i><span><b>Add Income / Expense</b><small>Record a new transaction</small></span></button><button class="f179-action" onclick="pspF179Tab('staff')"><i>👤</i><span><b>Staff & Salary</b><small>Manage monthly payroll</small></span></button><button class="f179-action" onclick="pspF179Tab('partners')"><i>◆</i><span><b>Partner Payouts</b><small>Revenue-share payments</small></span></button><button class="f179-action" onclick="pspF179Tab('reports')"><i>▤</i><span><b>Reports & Export</b><small>Download finance reports</small></span></button></div>`}
function dashboard(){const s=summary(),inc=incomeMap(),exp=expenseMap();return `${kpis()}<div class="f179-analytics"><div class="f179-card f179-chartbox"><div class="f179-card-head"><div><h3>📈 Income vs Expenses vs Profit</h3><p>Monthly finance trend</p></div></div><div class="f179-chart"><canvas id="f179Trend"></canvas></div></div><div class="f179-card f179-chartbox"><div class="f179-card-head"><div><h3>🧩 Income Breakdown</h3><p>Total income: ${money(s.income)}</p></div></div><div class="f179-donut-grid"><div class="f179-donut"><canvas id="f179IncomeDonut"></canvas><div class="f179-donut-center"><strong>${money(s.income)}</strong><span>100%</span></div></div><div class="f179-legend">${legend(inc)}</div></div></div><div class="f179-card f179-chartbox"><div class="f179-card-head"><div><h3>🧾 Expenses Breakdown</h3><p>Operating: ${money(s.op)}</p></div></div><div class="f179-donut-grid"><div class="f179-donut"><canvas id="f179ExpenseDonut"></canvas><div class="f179-donut-center"><strong>${money(s.op)}</strong><span>100%</span></div></div><div class="f179-legend">${legend(exp)}</div></div></div><div class="f179-card f179-chartbox"><div class="f179-card-head"><div><h3>📈 Monthly Profit Trend</h3><p>Last 12 months</p></div></div><div class="f179-chart"><canvas id="f179Profit"></canvas></div></div></div><div class="f179-mid"><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>📅 This Month Summary</h3><p>${esc(monthLabel())}</p></div><span class="f179-pill green">Current View</span></div><div class="f179-summary-grid"><div class="f179-mini" style="--accent:#20b373"><i>↑</i><div><span>Total Income</span><strong>${money(s.income)}</strong><small>${esc(monthLabel())}</small></div></div><div class="f179-mini" style="--accent:#ff4c57"><i>▣</i><div><span>Total Expenses</span><strong>${money(s.op)}</strong><small>Operating costs</small></div></div><div class="f179-mini" style="--accent:#347df5"><i>♟</i><div><span>Staff Salaries</span><strong>${money(s.salaries)}</strong><small>Payroll accrual</small></div></div><div class="f179-mini" style="--accent:#ff7900"><i>◇</i><div><span>Net Profit</span><strong>${money(s.net)}</strong><small>${s.margin.toFixed(2)}% margin</small></div></div></div></div><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>⚡ Quick Actions</h3><p>Most-used finance actions</p></div></div>${quickActions()}</div><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>⛓ Recent Transactions</h3><p>Latest money movement</p></div><button class="f179-link" onclick="pspF179Tab('transactions')">View All</button></div><div class="f179-table-wrap" style="max-height:245px"><table class="f179-table"><thead><tr><th>Date</th><th>Type</th><th>Category / Description</th><th>Amount</th><th>Status</th></tr></thead><tbody>${recentRows()}</tbody></table></div></div></div>${moneyWent()}<div class="f179-bottom"><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>📊 Monthly Profit & Loss</h3><p>Historical comparison</p></div><button class="f179-link" onclick="pspF179Tab('reports')">Yearly</button></div>${pnlTable()}</div><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>▤ Finance History</h3><p>Selected month</p></div></div>${historyRows()}</div><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>◷ Latest Activity Logs</h3><p>Finance audit trail</p></div><button class="f179-link" onclick="pspF179Tab('reports')">View All</button></div><div>${logRows(7)}</div></div></div><div class="f179-footer"><span><b>PP</b> PipSePaisa</span><span>Finance Management System · Secure & Audited</span></div>`}
function moneyWent(){const s=summary(),parts=[['Operating Expenses',s.op,'#ff4c57'],['Staff Salaries',s.salaries,'#347df5'],['Partner Share',s.partners,'#8a48dc'],['Company Profit',Math.max(s.net,0),'#20b373']],tot=Math.max(s.income,1);return `<div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>💸 Where the Money Went</h3><p>How ${money(s.income)} income was allocated this month</p></div></div><div class="f179-moneywent"><div class="f179-bars">${parts.map(([l,v,c])=>`<div class="f179-barline"><span>${l}</span><div class="f179-track"><i style="width:${Math.min(100,v/tot*100)}%;background:${c}"></i></div><strong>${money(v)}</strong></div>`).join('')}</div><div class="f179-card" style="padding:12px;background:#fff9ef"><div style="font-size:8px;color:var(--f-muted)">Actual company profit after operating costs, payroll and partner shares</div><div style="font-size:25px;font-weight:900;margin-top:7px;color:${s.net>=0?'#0b9f63':'#da3944'}">${money(s.net)}</div><div style="font-size:8px;color:var(--f-muted);margin-top:4px">Profit margin ${s.margin.toFixed(2)}%</div></div></div></div>`}
function pnlTable(){const ms=months(6).reverse();return `<div class="f179-table-wrap" style="max-height:none"><table class="f179-table"><thead><tr><th>Month</th><th>Total Income</th><th>Operating</th><th>Salaries</th><th>Partner Share</th><th>Net Profit</th><th>Margin</th></tr></thead><tbody>${ms.map(k=>{const s=summary(k);return `<tr><td><strong>${esc(monthLabel(k))}</strong></td><td>${money(s.income)}</td><td>${money(s.op)}</td><td>${money(s.salaries)}</td><td>${money(s.partners)}</td><td><strong>${money(s.net)}</strong></td><td>${s.margin.toFixed(2)}%</td></tr>`}).join('')}</tbody></table></div>`}
function historyRows(){const s=summary();return `<div class="f179-history"><div class="f179-history-row"><span>Income</span><strong>${money(s.income)}</strong></div><div class="f179-history-row"><span>Operating Expenses</span><strong style="color:#df3c45">${money(s.op)}</strong></div><div class="f179-history-row"><span>Salaries</span><strong>${money(s.salaries)}</strong></div><div class="f179-history-row"><span>Partner Share</span><strong>${money(s.partners)}</strong></div><div class="f179-history-row"><span>Net Profit</span><strong style="color:#e87900">${money(s.net)}</strong></div><div class="f179-history-row"><span>Profit Margin</span><strong style="color:#e87900">${s.margin.toFixed(2)}%</strong></div><div class="f179-history-row"><span>Pending</span><strong>${money(s.pending)}</strong></div></div>`}
function logRows(limit=50){const a=F.data.audit.slice(0,limit);return a.length?a.map(x=>`<div class="f179-log"><span class="f179-avatar">${esc((x.actor_name||'A').slice(0,1).toUpperCase())}</span><b>${esc(x.actor_name||'Admin')}</b><div><div class="act">${esc(String(x.action||'').toUpperCase())} · ${esc(x.table_name||'finance')}</div><small>${esc(x.record_id||'')}</small></div><small>${esc(dt(x.created_at))}</small></div>`).join(''):`<div class="f179-empty">No finance audit records yet.</div>`}
function renderDashboardCharts(){if(F.tab!=='dashboard'||typeof Chart==='undefined')return;Object.values(F.charts).forEach(c=>{try{c.destroy()}catch(_){}});F.charts={};const ms=months(12),labels=ms.map(monthShort),inc=ms.map(k=>summary(k).income),out=ms.map(k=>summary(k).op+summary(k).salaries+summary(k).partners),prof=ms.map(k=>summary(k).net),grid='rgba(120,130,145,.12)';function mk(id,cfg){const el=q('#'+id);if(el)F.charts[id]=new Chart(el,cfg)}mk('f179Trend',{type:'bar',data:{labels,datasets:[{label:'Income',data:inc,backgroundColor:'#20b373',borderRadius:4},{label:'Expenses',data:out,backgroundColor:'#ff4c57',borderRadius:4},{label:'Net Profit',data:prof,type:'line',borderColor:'#fb9201',backgroundColor:'#fb9201',tension:.35,pointRadius:3}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{labels:{boxWidth:9,font:{size:8}}}},scales:{x:{grid:{display:false},ticks:{font:{size:7}}},y:{grid:{color:grid},ticks:{font:{size:7},callback:v=>'$'+v}}}}});mk('f179Profit',{type:'line',data:{labels,datasets:[{label:'Income',data:inc,borderColor:'#20b373',tension:.35,pointRadius:3},{label:'Expenses',data:out,borderColor:'#ff4c57',tension:.35,pointRadius:3},{label:'Net Profit',data:prof,borderColor:'#fb9201',tension:.35,pointRadius:3}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{labels:{boxWidth:9,font:{size:8}}}},scales:{x:{grid:{display:false},ticks:{font:{size:7}}},y:{grid:{color:grid},ticks:{font:{size:7},callback:v=>'$'+v}}}}});function donut(id,m){const e=Object.entries(m),vals=e.length?e.map(x=>x[1]):[1],labs=e.length?e.map(x=>x[0]):['No data'];mk(id,{type:'doughnut',data:{labels:labs,datasets:[{data:vals,backgroundColor:e.length?C.slice(0,e.length):['#e9e1d5'],borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,cutout:'68%',plugins:{legend:{display:false},tooltip:{enabled:!!e.length}}}})}donut('f179IncomeDonut',incomeMap());donut('f179ExpenseDonut',expenseMap())}

function transactionsView(){const cats=[...new Set(F.data.tx.map(x=>x.category).filter(Boolean))].sort();let rows=F.data.tx.filter(r=>String(r.period_month||'').slice(0,7)===F.month);const f=F.filters;if(f.q){const z=f.q.toLowerCase();rows=rows.filter(r=>[r.txn_code,r.category,r.subcategory,r.description,r.counterparty,r.source_ref].some(v=>String(v||'').toLowerCase().includes(z)))}if(f.type!=='all')rows=rows.filter(r=>r.transaction_type===f.type);if(f.status!=='all')rows=rows.filter(r=>r.status===f.status);if(f.category!=='all')rows=rows.filter(r=>r.category===f.category);rows.sort((a,b)=>new Date(b.transaction_date)-new Date(a.transaction_date)||new Date(b.created_at)-new Date(a.created_at));return `<div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>💳 Complete Transaction Ledger</h3><p>Every company money movement has a unique transaction ID and audit trail.</p></div><button class="f179-btn primary" onclick="pspF179OpenTxn()">＋ Add Transaction</button></div><div class="f179-toolbar"><input class="grow" placeholder="Search ID, category, description, counterparty…" value="${esc(f.q)}" oninput="pspF179Filter('q',this.value)"><select onchange="pspF179Filter('type',this.value)"><option value="all">All Types</option>${['income','expense','salary','partner_payout','adjustment','receivable','payable'].map(x=>`<option ${f.type===x?'selected':''}>${x}</option>`).join('')}</select><select onchange="pspF179Filter('status',this.value)"><option value="all">All Statuses</option>${['paid','pending','pending_approval','approved','rejected','cancelled'].map(x=>`<option ${f.status===x?'selected':''}>${x}</option>`).join('')}</select><select onchange="pspF179Filter('category',this.value)"><option value="all">All Categories</option>${cats.map(x=>`<option ${f.category===x?'selected':''}>${esc(x)}</option>`).join('')}</select><button class="f179-btn" onclick="pspF179ExportExcel()">Excel</button></div><div class="f179-table-wrap"><table class="f179-table"><thead><tr><th>Txn ID</th><th>Date</th><th>Type</th><th>Category / Description</th><th>Account</th><th>Amount</th><th>Status</th><th>Source</th><th>Actions</th></tr></thead><tbody>${rows.length?rows.map(r=>txnRow(r)).join(''):`<tr><td colspan="9" class="f179-empty">No transactions match these filters.</td></tr>`}</tbody></table></div></div>`}
function txnRow(r){const acc=byId(F.data.accounts,r.account_id);let actions=`<button class="f179-mini-btn" onclick="pspF179ViewTxn('${r.id}')">Details</button>`;if(!closed()&&r.source==='manual'&&!['cancelled','rejected'].includes(r.status))actions+=`<button class="f179-mini-btn" onclick="pspF179OpenTxn('${r.id}')">Edit</button>`;if(r.status==='pending_approval')actions+=`<button class="f179-mini-btn primary" onclick="pspF179ApproveTxn('${r.id}')">Approve</button><button class="f179-mini-btn bad" onclick="pspF179RejectTxn('${r.id}')">Reject</button>`;if(['approved','pending'].includes(r.status))actions+=`<button class="f179-mini-btn orange" onclick="pspF179MarkTxnPaid('${r.id}')">Mark Paid</button>`;if(!['cancelled','rejected'].includes(r.status)&&r.source!=='automatic')actions+=`<button class="f179-mini-btn bad" onclick="pspF179CancelTxn('${r.id}')">Cancel</button>`;return `<tr><td><strong>${esc(r.txn_code||r.id.slice(0,8))}</strong></td><td>${esc(r.transaction_date)}</td><td>${typePill(r)}</td><td><strong>${esc(r.category)}</strong><div style="font-size:6.5px;color:var(--f-muted)">${esc(r.description||r.subcategory||'')}</div></td><td>${esc(acc?.name||'—')}</td><td class="f179-money ${r.direction==='credit'?'plus':'minus'}">${r.direction==='credit'?'+':'-'}${money(r.amount,r.currency)}</td><td>${statusPill(r.status)}</td><td><span class="f179-pill ${r.source==='automatic'?'blue':'gray'}">${esc(r.source)}</span></td><td><div class="f179-row-actions">${actions}</div></td></tr>`}
function incomeExpenseView(){const bs=budgetState(),rec=F.data.recurring,obs=F.data.obligations;return `<div class="f179-grid2"><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>💰 Income Management</h3><p>Paid Course Revenue is automatic; commissions and other income can be added manually.</p></div><button class="f179-btn primary" onclick="pspF179OpenTxn(null,'income')">＋ Add Income</button></div>${sourceList(incomeMap())}</div><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>🧾 Expense Management</h3><p>Operating costs with receipt, vendor, account and payment status.</p></div><button class="f179-btn primary" onclick="pspF179OpenTxn(null,'expense')">＋ Add Expense</button></div>${sourceList(expenseMap())}</div></div><div class="f179-grid2" style="margin-top:9px"><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>🔁 Recurring Income & Expenses</h3><p>Monthly items generate automatically.</p></div><button class="f179-btn" onclick="pspF179OpenRecurring()">＋ Recurring Item</button></div><div class="f179-table-wrap" style="max-height:330px"><table class="f179-table"><thead><tr><th>Item</th><th>Type</th><th>Category</th><th>Amount</th><th>Due Day</th><th>Status</th></tr></thead><tbody>${rec.length?rec.map(r=>`<tr><td><strong>${esc(r.title)}</strong></td><td>${esc(r.item_type)}</td><td>${esc(r.category)}</td><td>${money(r.amount,r.currency)}</td><td>${r.due_day}</td><td>${r.active?statusPill('approved'):statusPill('cancelled')}</td></tr>`).join(''):`<tr><td colspan="6" class="f179-empty">No recurring items.</td></tr>`}</tbody></table></div></div><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>📌 Payables & Receivables</h3><p>Money the company owes or expects to receive.</p></div><button class="f179-btn" onclick="pspF179OpenObligation()">＋ Add</button></div><div class="f179-table-wrap" style="max-height:330px"><table class="f179-table"><thead><tr><th>Type</th><th>Title</th><th>Counterparty</th><th>Amount</th><th>Due</th><th>Status</th><th>Action</th></tr></thead><tbody>${obs.length?obs.map(o=>`<tr><td>${statusPill(o.obligation_type)}</td><td><strong>${esc(o.title)}</strong></td><td>${esc(o.counterparty||'—')}</td><td>${money(o.amount,o.currency)}</td><td>${esc(o.due_date||'—')}</td><td>${statusPill(o.status)}</td><td>${['paid','received','cancelled'].includes(o.status)?'—':`<button class="f179-mini-btn primary" onclick="pspF179SettleObligation('${o.id}')">${o.obligation_type==='receivable'?'Mark Received':'Mark Paid'}</button>`}</td></tr>`).join(''):`<tr><td colspan="7" class="f179-empty">No payables or receivables.</td></tr>`}</tbody></table></div></div></div><div class="f179-card f179-pad" style="margin-top:9px"><div class="f179-card-head"><div><h3>🎯 Budget Control</h3><p>Track category limits and receive warnings near the threshold.</p></div><button class="f179-btn" onclick="pspF179OpenBudget()">＋ Set Budget</button></div><div class="f179-grid3">${bs.length?bs.map(b=>`<div class="f179-budget ${b.pct>=100?'bad':b.pct>=b.warning?'warn':''}"><div class="f179-budget-head"><strong>${esc(b.category)}</strong><span>${b.pct.toFixed(1)}%</span></div><div class="f179-budget-track"><i style="width:${Math.min(100,b.pct)}%"></i></div><div class="f179-help" style="margin-top:6px">Used ${money(b.used)} of ${money(b.budget)} · warning at ${b.warning}%</div></div>`).join(''):`<div class="f179-empty">No budgets set for ${esc(monthLabel())}.</div>`}</div></div>`}
function sourceList(m){const a=Object.entries(m).sort((x,y)=>y[1]-x[1]);return a.length?`<div class="f179-history">${a.map(([k,v])=>`<div class="f179-history-row"><span>${esc(k)}</span><strong>${money(v)}</strong></div>`).join('')}</div>`:`<div class="f179-empty">No entries this month.</div>`}
function budgetState(){const used=expenseMap();return F.data.budgets.filter(b=>String(b.period_month||'').slice(0,7)===F.month).map(b=>({id:b.id,category:b.category,budget:n(b.budget_amount),warning:n(b.warning_percent)||80,used:n(used[b.category]),pct:n(b.budget_amount)>0?n(used[b.category])/n(b.budget_amount)*100:0}))}
function staffView(){const runs=monthSalary();return `<div class="f179-grid2"><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>👥 Staff Profiles</h3><p>Role, fixed monthly salary and payout details.</p></div><button class="f179-btn primary" onclick="pspF179OpenStaff()">＋ Add Staff</button></div><div class="f179-table-wrap"><table class="f179-table"><thead><tr><th>Name</th><th>Role</th><th>Monthly Salary</th><th>Due Day</th><th>Status</th><th>Action</th></tr></thead><tbody>${F.data.staff.length?F.data.staff.map(s=>`<tr><td><strong>${esc(s.full_name)}</strong><div style="font-size:6.5px;color:var(--f-muted)">${esc(s.email||'')}</div></td><td>${esc(s.role_title||'—')}</td><td>${money(s.monthly_salary,s.currency)}</td><td>${s.due_day}</td><td>${s.active?statusPill('approved'):statusPill('cancelled')}</td><td><button class="f179-mini-btn" onclick="pspF179OpenStaff('${s.id}')">Edit</button></td></tr>`).join(''):`<tr><td colspan="6" class="f179-empty">No staff configured.</td></tr>`}</tbody></table></div></div><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>⚙ Monthly Salary Processing</h3><p>Generate salary queue for ${esc(monthLabel())}.</p></div><button class="f179-btn primary" onclick="pspF179ProcessSalaries()">Process Monthly Salaries</button></div><div class="f179-summary-grid"><div class="f179-mini" style="--accent:#347df5"><i>♟</i><div><span>Total Payable</span><strong>${money(runs.reduce((s,r)=>s+n(r.payable_amount),0))}</strong><small>${runs.length} salary records</small></div></div><div class="f179-mini" style="--accent:#20b373"><i>✓</i><div><span>Paid</span><strong>${money(runs.filter(r=>r.status==='paid').reduce((s,r)=>s+n(r.payable_amount),0))}</strong><small>${runs.filter(r=>r.status==='paid').length} paid</small></div></div></div></div></div><div class="f179-card f179-pad" style="margin-top:9px"><div class="f179-card-head"><div><h3>🧾 Salary Queue</h3><p>Bonus, deduction, advance, payable amount and proof.</p></div></div><div class="f179-table-wrap"><table class="f179-table"><thead><tr><th>Staff</th><th>Base</th><th>Bonus</th><th>Deduction</th><th>Advance</th><th>Payable</th><th>Due</th><th>Status</th><th>Proof</th><th>Action</th></tr></thead><tbody>${runs.length?runs.map(r=>{const s=byId(F.data.staff,r.staff_id);return `<tr><td><strong>${esc(s?.full_name||'Staff')}</strong></td><td>${money(r.base_salary)}</td><td>${money(r.bonus)}</td><td>${money(r.deduction)}</td><td>${money(r.advance)}</td><td><strong>${money(r.payable_amount)}</strong></td><td>${esc(r.due_date||'—')}</td><td>${statusPill(r.status)}</td><td>${r.receipt_path?`<button class="f179-mini-btn" onclick="pspF179Receipt('${esc(r.receipt_path)}')">View</button>`:'—'}</td><td>${r.status==='paid'?'—':`<button class="f179-mini-btn primary" onclick="pspF179PaySalary('${r.id}')">Pay Salary</button>`}</td></tr>`}).join(''):`<tr><td colspan="10" class="f179-empty">No salary queue. Click Process Monthly Salaries.</td></tr>`}</tbody></table></div></div>`}
function partnerView(){const ps=monthPayout();return `<div class="f179-grid2"><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>🤝 Partner / Instructor Rules</h3><p>Set revenue-share basis and percentage.</p></div><button class="f179-btn primary" onclick="pspF179OpenPartner()">＋ Add Partner</button></div><div class="f179-table-wrap"><table class="f179-table"><thead><tr><th>Partner</th><th>Basis</th><th>Share</th><th>Status</th><th>Action</th></tr></thead><tbody>${F.data.partners.length?F.data.partners.map(p=>`<tr><td><strong>${esc(p.partner_name)}</strong></td><td>${esc(p.share_basis.replace(/_/g,' '))}</td><td>${n(p.share_percent).toFixed(2)}%</td><td>${p.active?statusPill('approved'):statusPill('cancelled')}</td><td><button class="f179-mini-btn" onclick="pspF179OpenPartner('${p.id}')">Edit</button></td></tr>`).join(''):`<tr><td colspan="5" class="f179-empty">No partners configured.</td></tr>`}</tbody></table></div></div><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>💸 Payout Summary</h3><p>${esc(monthLabel())}</p></div><button class="f179-btn" onclick="pspF179SyncPartners()">↻ Sync Amounts Due</button></div><div class="f179-summary-grid"><div class="f179-mini" style="--accent:#8a48dc"><i>◆</i><div><span>Total Due</span><strong>${money(ps.reduce((s,r)=>s+n(r.amount_due),0))}</strong><small>Revenue share accrued</small></div></div><div class="f179-mini" style="--accent:#20b373"><i>✓</i><div><span>Total Paid</span><strong>${money(ps.reduce((s,r)=>s+n(r.amount_paid),0))}</strong><small>Recorded payouts</small></div></div></div></div></div><div class="f179-card f179-pad" style="margin-top:9px"><div class="f179-card-head"><div><h3>💰 Partner Payout Tracking</h3><p>Due, paid and outstanding balance.</p></div></div><div class="f179-table-wrap"><table class="f179-table"><thead><tr><th>Partner</th><th>Basis Amount</th><th>Share</th><th>Due</th><th>Paid</th><th>Balance</th><th>Status</th><th>Proof</th><th>Action</th></tr></thead><tbody>${ps.length?ps.map(r=>{const p=byId(F.data.partners,r.partner_id),bal=Math.max(0,n(r.amount_due)-n(r.amount_paid));return `<tr><td><strong>${esc(p?.partner_name||'Partner')}</strong></td><td>${money(r.basis_amount)}</td><td>${n(r.share_percent).toFixed(2)}%</td><td>${money(r.amount_due)}</td><td>${money(r.amount_paid)}</td><td><strong>${money(bal)}</strong></td><td>${statusPill(r.status)}</td><td>${r.receipt_path?`<button class="f179-mini-btn" onclick="pspF179Receipt('${esc(r.receipt_path)}')">View</button>`:'—'}</td><td>${bal>0?`<button class="f179-mini-btn primary" onclick="pspF179PayPartner('${r.id}')">Record Payment</button>`:'—'}</td></tr>`}).join(''):`<tr><td colspan="9" class="f179-empty">No payout rows. Add a partner and sync amounts due.</td></tr>`}</tbody></table></div></div>`}
function accountsView(){return `<div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>🏦 Company Accounts & Wallets</h3><p>Main Bank, Cash, Gateway, USDT/Wallet and other balances.</p></div><button class="f179-btn primary" onclick="pspF179OpenAccount()">＋ Add Account</button></div><div class="f179-grid3">${F.data.balances.length?F.data.balances.map(a=>`<div class="f179-account"><div><strong>${esc(a.name)}</strong><small>${esc(a.account_type)} · ${esc(a.currency)}</small></div><div style="text-align:right"><strong>${money(a.balance,a.currency)}</strong><small>Approx. available balance</small></div></div>`).join(''):`<div class="f179-empty">No accounts found.</div>`}</div></div><div class="f179-grid2" style="margin-top:9px"><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>⚙ Finance Settings</h3><p>Approval threshold for large manual expenses.</p></div></div><div class="f179-field"><label>Large expense approval threshold (USD)</label><input id="f179ApprovalThreshold" type="number" min="0" step="1" value="${approvalThreshold()}"></div><button class="f179-btn primary" style="margin-top:9px" onclick="pspF179SaveSettings()">Save Setting</button></div><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>🧮 Balance Logic</h3><p>Opening balance + paid credits − paid debits.</p></div></div><div class="f179-help">Pending, rejected and cancelled transactions do not change an account balance. Selecting Paid From / Received In on each transaction keeps balances meaningful.</div></div></div>`}
function approvalThreshold(){try{const x=F.data.settings?.find(x=>x.setting_key==='approval_threshold');return n(x?.setting_value?.amount)||1000}catch(_){return 1000}}
function reportsView(){return `<div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>📄 Reports & Export</h3><p>Monthly P&L, transaction exports and permanent finance audit.</p></div><div class="f179-row-actions"><button class="f179-btn" onclick="pspF179ExportExcel()">Excel Report</button><button class="f179-btn primary" onclick="pspF179ExportPdf()">PDF / Print</button></div></div>${pnlTable()}</div><div class="f179-grid2" style="margin-top:9px"><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>🛡 Finance Audit Log</h3><p>Old value + new value + admin + date/time. Append-only.</p></div></div><div style="max-height:520px;overflow:auto">${logRows(100)}</div></div><div class="f179-card f179-pad"><div class="f179-card-head"><div><h3>🔒 Month Closing</h3><p>Closed months are locked. Corrections use Adjustment entries.</p></div></div><div class="f179-history">${F.data.closures.slice().sort((a,b)=>String(b.period_month).localeCompare(String(a.period_month))).map(c=>`<div class="f179-history-row"><span>${esc(monthLabel(String(c.period_month).slice(0,7)))}</span><strong>${esc(dt(c.closed_at))}</strong></div>`).join('')||'<div class="f179-empty">No closed months yet.</div>'}</div></div></div>`}
function viewHtml(){if(F.tab==='transactions')return transactionsView();if(F.tab==='income')return incomeExpenseView();if(F.tab==='staff')return staffView();if(F.tab==='partners')return partnerView();if(F.tab==='accounts')return accountsView();if(F.tab==='reports')return reportsView();return dashboard()}
function arrSig(a){return (a||[]).map(r=>[r.id||r.txn_code||r.setting_key||'',r.updated_at||r.created_at||r.period_month||'',r.status||'',r.amount||r.payable_amount||r.amount_due||r.opening_balance||'',r.category||r.name||r.full_name||r.partner_name||''].join('~')).join('|')}
function renderKey(){return [F.tab,F.month,JSON.stringify(F.filters),arrSig(F.data.tx),arrSig(F.data.accounts),arrSig(F.data.balances),arrSig(F.data.staff),arrSig(F.data.salary),arrSig(F.data.partners),arrSig(F.data.payouts),arrSig(F.data.obligations),arrSig(F.data.recurring),arrSig(F.data.budgets),arrSig(F.data.closures),arrSig(F.data.audit),arrSig(F.data.settings)].join('§')}
function render(force=false){const root=q('#f179Root');if(!root)return;const key=renderKey();if(!force&&F._lastRenderKey===key){syncTopbar();return}root.innerHTML=header()+`<div class="f179-view active">${viewHtml()}</div>`;F._lastRenderKey=key;if(F.tab==='dashboard')setTimeout(renderDashboardCharts,20);syncTopbar()}
function syncTopbar(){const h=q('.page-title h2'),p=q('.page-title p');if(q('#page-revenue.page.active')){if(h)h.textContent='Finance & Accounts';if(p)p.textContent='Company finance management, payroll, payouts, accounts and audit'}}
async function prepare(){const c=db();if(!c)return;const d=monthStart();await Promise.allSettled([c.rpc('psp_finance_prepare_salaries',{p_month:d}),c.rpc('psp_finance_generate_recurring',{p_month:d}),c.rpc('psp_finance_sync_partner_payouts',{p_month:d})])}
async function load(opts={}){const c=db();if(!c)return;if(F._loadPromise)return F._loadPromise;const force=!!opts.force,now=Date.now();if(!force&&F._loaded&&now-F._lastLoadAt<2500){render(false);return}F._loadPromise=(async()=>{F.loading=true;const root=q('#f179Root');if(root&&!F._loaded&&!F.data.tx.length&&root.querySelector('.f179-loading')==null)root.innerHTML='<div class="f179-loading">Loading Finance & Accounts…</div>';if(F._preparedMonth!==F.month){await prepare();F._preparedMonth=F.month}const ms=months(12),start=ms[0]+'-01',end=monthEnd(F.month);const req=[c.from('finance_transactions').select('*').gte('period_month',start).lt('period_month',end).order('transaction_date',{ascending:false}).order('created_at',{ascending:false}),c.from('finance_accounts').select('*').eq('active',true).order('created_at'),c.rpc('psp_finance_account_balances'),c.from('finance_staff').select('*').order('full_name'),c.from('finance_salary_runs').select('*').gte('period_month',start).lt('period_month',end).order('period_month',{ascending:false}),c.from('finance_partners').select('*').order('partner_name'),c.from('finance_partner_payouts').select('*').gte('period_month',start).lt('period_month',end).order('period_month',{ascending:false}),c.from('finance_obligations').select('*').order('due_date',{ascending:true}),c.from('finance_recurring_items').select('*').order('created_at'),c.from('finance_budgets').select('*').gte('period_month',start).lt('period_month',end),c.from('finance_month_closures').select('*').gte('period_month',start).lt('period_month',end).order('period_month',{ascending:false}),c.from('finance_audit_log').select('*').order('created_at',{ascending:false}).limit(200),c.from('finance_settings').select('*')];const rr=await Promise.all(req);const names=['tx','accounts','balances','staff','salary','partners','payouts','obligations','recurring','budgets','closures','audit','settings'];rr.forEach((r,i)=>{if(r.error)console.warn('[V182 finance]',names[i],r.error.message);else F.data[names[i]]=r.data||[]});F.loading=false;F._loaded=true;F._lastLoadAt=Date.now();render(force)})().finally(()=>{F._loadPromise=null});return F._loadPromise}

async function upload(file,folder='transactions'){if(!file)return null;const c=db(),ext=(file.name.split('.').pop()||'bin').replace(/[^a-z0-9]/gi,''),path=`${folder}/${new Date().toISOString().slice(0,7)}/${crypto.randomUUID()}.${ext}`;const r=await c.storage.from('finance-documents').upload(path,file,{upsert:false,contentType:file.type||undefined});if(r.error)throw r.error;return path}
function modal(title,sub,body,actions){const m=q('#f179Modal'),c=q('#f179ModalCard');c.innerHTML=`<div class="f179-modal-head"><div><h3>${title}</h3><p>${sub||''}</p></div><button class="f179-x" onclick="pspF179CloseModal()">×</button></div><div class="f179-modal-body">${body}</div><div class="f179-modal-actions">${actions||'<button class="f179-btn" onclick="pspF179CloseModal()">Close</button>'}</div>`;m.classList.add('open')}
window.pspF179CloseModal=()=>q('#f179Modal')?.classList.remove('open');
function accountOptions(sel){return `<option value="">No account selected</option>${F.data.accounts.map(a=>`<option value="${a.id}" ${String(sel)===String(a.id)?'selected':''}>${esc(a.name)} (${esc(a.currency)})</option>`).join('')}`}
function txnForm(r={},preset){const t=preset||r.transaction_type||'income',dir=r.direction||(t==='income'||t==='receivable'?'credit':'debit'),cl=closed();return `<div class="f179-form"><div class="f179-field"><label>Transaction Type</label><select id="fmType" onchange="pspF179TxnTypeChange()">${['income','expense','adjustment','receivable','payable'].map(x=>`<option ${t===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="f179-field"><label>Direction</label><select id="fmDirection"><option value="credit" ${dir==='credit'?'selected':''}>Credit / Money In</option><option value="debit" ${dir==='debit'?'selected':''}>Debit / Money Out</option></select></div><div class="f179-field"><label>Category</label><input id="fmCategory" value="${esc(r.category||defaultCategory(t))}" placeholder="Marketing, Broker Commission, Software…"></div><div class="f179-field"><label>Amount (USD)</label><input id="fmAmount" type="number" min="0.01" step="0.01" value="${r.amount||''}"></div><div class="f179-field"><label>Received In / Paid From</label><select id="fmAccount">${accountOptions(r.account_id)}</select></div><div class="f179-field"><label>Payment Method</label><select id="fmMethod"><option value="">Select</option>${['Bank Transfer','Cash','USDT','Card','Payment Gateway','Other'].map(x=>`<option ${r.payment_method===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="f179-field"><label>Transaction Date</label><input id="fmDate" type="date" value="${esc(r.transaction_date||new Date().toISOString().slice(0,10))}"></div><div class="f179-field"><label>Status</label><select id="fmStatus">${['paid','pending','approved','draft'].map(x=>`<option ${String(r.status||'paid')===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="f179-field"><label>Counterparty / Vendor</label><input id="fmCounterparty" value="${esc(r.counterparty||'')}"></div><div class="f179-field"><label>Due Date (optional)</label><input id="fmDue" type="date" value="${esc(r.due_date||'')}"></div><div class="f179-field full"><label>Description</label><textarea id="fmDesc" rows="3" placeholder="What is this transaction for?">${esc(r.description||'')}</textarea></div><div class="f179-field full"><label>Receipt / Invoice / Proof</label><input id="fmFile" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"><div class="f179-help">Max 10MB. Existing proof remains if no new file is selected.</div></div>${cl?'<div class="f179-field full"><div class="f179-alert warn">This month is closed. Only Adjustment transactions are allowed.</div></div>':''}</div>`}
function defaultCategory(t){return t==='income'?'Other Income':t==='expense'?'Other Expense':t==='receivable'?'Receivable':t==='payable'?'Payable':'Adjustment'}
window.pspF179TxnTypeChange=function(){const t=q('#fmType').value,d=q('#fmDirection');if(t==='income'||t==='receivable')d.value='credit';else if(t==='expense'||t==='payable')d.value='debit'};
window.pspF179OpenTxn=function(id,preset){const r=id?byId(F.data.tx,id):{},cl=closed();if(cl&&!id&&preset!=='adjustment')preset='adjustment';if(id&&cl)return toast('Closed months cannot be edited. Add an Adjustment entry instead.','error');modal(id?'Edit Transaction':'Add Transaction',cl?'Closed month corrections are recorded as Adjustment entries.':'Income, expense, account, payment status and proof.',txnForm(r,preset),`<button class="f179-btn" onclick="pspF179CloseModal()">Cancel</button><button class="f179-btn primary" onclick="pspF179SaveTxn('${id||''}')">${id?'Save Changes':'Save Transaction'}</button>`)};
window.pspF179SaveTxn=async function(id){const c=db();try{const type=q('#fmType').value,amount=n(q('#fmAmount').value),file=q('#fmFile').files[0];if(!amount||!q('#fmCategory').value.trim())return toast('Category and valid amount are required.','error');let path=id?byId(F.data.tx,id)?.receipt_path:null;if(file)path=await upload(file,'transactions');const payload={transaction_type:type,direction:q('#fmDirection').value,category:q('#fmCategory').value.trim(),description:q('#fmDesc').value.trim()||null,amount,currency:'USD',account_id:q('#fmAccount').value||null,counterparty:q('#fmCounterparty').value.trim()||null,payment_method:q('#fmMethod').value||null,status:q('#fmStatus').value,transaction_date:q('#fmDate').value,due_date:q('#fmDue').value||null,receipt_path:path,source:id?byId(F.data.tx,id)?.source||'manual':type==='adjustment'?'adjustment':'manual',created_by:curAdminId(),updated_at:new Date().toISOString()};const old=id?byId(F.data.tx,id):null,r=id?await c.from('finance_transactions').update(payload).eq('id',id):await c.from('finance_transactions').insert(payload).select().single();if(r.error)throw r.error;await audit(id?'finance_transaction_update':'finance_transaction_create',`${id?'Updated':'Created'} ${payload.category}`,'finance_transaction',id||r.data?.id,old,payload);pspF179CloseModal();await load();toast(id?'Transaction updated.':'Transaction saved.')}catch(e){toast(e.message||String(e),'error')}};
window.pspF179ViewTxn=function(id){const r=byId(F.data.tx,id);if(!r)return;modal(`Transaction ${esc(r.txn_code||'')}`,`${esc(r.category)} · ${esc(r.status)}`,`<div class="f179-history">${[['Date',r.transaction_date],['Type',r.transaction_type],['Direction',r.direction],['Amount',money(r.amount,r.currency)],['Account',byId(F.data.accounts,r.account_id)?.name||'—'],['Counterparty',r.counterparty||'—'],['Payment Method',r.payment_method||'—'],['Due Date',r.due_date||'—'],['Source',r.source],['Source Ref',r.source_ref||'—'],['Description',r.description||'—']].map(([a,b])=>`<div class="f179-history-row"><span>${a}</span><strong>${esc(b)}</strong></div>`).join('')}</div>${r.receipt_path?`<button class="f179-btn" style="margin-top:10px" onclick="pspF179Receipt('${esc(r.receipt_path)}')">View Receipt / Proof</button>`:''}`)};
window.pspF179ApproveTxn=async id=>{const c=db(),r=byId(F.data.tx,id);if(!await confirmX('Approve this expense?'))return;const out=await c.from('finance_transactions').update({status:'approved',approved_by:curAdminId(),approved_at:new Date().toISOString(),updated_at:new Date().toISOString(),metadata:{...(r.metadata||{}),approval_override:'true'}}).eq('id',id);if(out.error)return toast(out.error.message,'error');await audit('finance_approve','Approved finance transaction','finance_transaction',id,r,{status:'approved'});await load()};
window.pspF179RejectTxn=async id=>{const c=db(),r=byId(F.data.tx,id);if(!r)return;const reason=prompt('Rejection reason:','Expense not approved.');if(reason===null)return;const out=await c.from('finance_transactions').update({status:'rejected',updated_at:new Date().toISOString(),metadata:{...(r.metadata||{}),rejection_reason:String(reason||'').trim()}}).eq('id',id);if(out.error)return toast(out.error.message,'error');await audit('finance_reject','Rejected finance transaction','finance_transaction',id,r,{status:'rejected',reason:String(reason||'').trim()});await load()};
window.pspF179MarkTxnPaid=async id=>{const c=db(),r=byId(F.data.tx,id);const out=await c.from('finance_transactions').update({status:'paid',paid_at:new Date().toISOString(),updated_at:new Date().toISOString(),metadata:{...(r.metadata||{}),approval_override:'true'}}).eq('id',id);if(out.error)return toast(out.error.message,'error');await audit('finance_paid','Marked transaction paid','finance_transaction',id,r,{status:'paid'});await load()};
window.pspF179CancelTxn=async id=>{const c=db(),r=byId(F.data.tx,id);if(!await confirmX('Cancel this transaction? It will remain in audit/history.'))return;const out=await c.from('finance_transactions').update({status:'cancelled',updated_at:new Date().toISOString()}).eq('id',id);if(out.error)return toast(out.error.message,'error');await audit('finance_cancel','Cancelled finance transaction','finance_transaction',id,r,{status:'cancelled'});await load()};
window.pspF179Receipt=async path=>{const c=db();const r=await c.storage.from('finance-documents').createSignedUrl(path,600);if(r.error)return toast(r.error.message,'error');window.open(r.data.signedUrl,'_blank')};

function simpleForm(fields){return `<div class="f179-form">${fields.join('')}</div>`}function fld(label,id,type='text',val='',extra=''){return `<div class="f179-field ${extra.includes('full')?'full':''}"><label>${label}</label><input id="${id}" type="${type}" value="${esc(val)}" ${extra.replace('full','')}></div>`}
window.pspF179OpenStaff=function(id){const s=id?byId(F.data.staff,id):{};modal(id?'Edit Staff':'Add Staff','Fixed salary, role, due day and payout details.',simpleForm([fld('Full Name','fsName','text',s.full_name||''),fld('Role / Position','fsRole','text',s.role_title||''),fld('Email','fsEmail','email',s.email||''),fld('Monthly Salary','fsSalary','number',s.monthly_salary||0,'step="0.01" min="0"'),`<div class="f179-field"><label>Currency</label><select id="fsCurrency"><option value="USD">USD</option></select><div class="f179-help">Company finance totals are maintained in USD.</div></div>`,fld('Salary Due Day','fsDue','number',s.due_day||1,'min="1" max="28"'),fld('Default Bonus','fsBonus','number',s.bonus_default||0,'step="0.01" min="0"'),fld('Default Deduction','fsDeduct','number',s.deduction_default||0,'step="0.01" min="0"'),`<div class="f179-field full"><label>Payout Details</label><textarea id="fsPayout" rows="2">${esc(s.payout_account||'')}</textarea></div>`]),`<button class="f179-btn" onclick="pspF179CloseModal()">Cancel</button><button class="f179-btn primary" onclick="pspF179SaveStaff('${id||''}')">Save Staff</button>`)};
window.pspF179SaveStaff=async id=>{const c=db(),payload={full_name:q('#fsName').value.trim(),role_title:q('#fsRole').value.trim()||null,email:q('#fsEmail').value.trim()||null,monthly_salary:n(q('#fsSalary').value),currency:q('#fsCurrency').value,due_day:n(q('#fsDue').value)||1,bonus_default:n(q('#fsBonus').value),deduction_default:n(q('#fsDeduct').value),payout_account:q('#fsPayout').value.trim()||null,active:true,updated_at:new Date().toISOString(),created_by:curAdminId()};if(!payload.full_name)return toast('Staff name is required.','error');const r=id?await c.from('finance_staff').update(payload).eq('id',id):await c.from('finance_staff').insert(payload);if(r.error)return toast(r.error.message,'error');await audit(id?'finance_staff_update':'finance_staff_create','Saved staff compensation','finance_staff',id||null,null,payload);pspF179CloseModal();await load()};
window.pspF179ProcessSalaries=async()=>{const c=db();const r=await c.rpc('psp_finance_prepare_salaries',{p_month:monthStart()});if(r.error)return toast(r.error.message,'error');await audit('salary_process','Processed monthly salary queue','finance_salary',F.month);await load();toast('Monthly salary queue prepared.')};
window.pspF179PaySalary=function(id){const r=byId(F.data.salary,id),s=byId(F.data.staff,r.staff_id);modal('Pay Salary',`${esc(s?.full_name||'Staff')} · ${money(r.payable_amount)}`,simpleForm([`<div class="f179-field"><label>Paid From</label><select id="payAccount">${accountOptions()}</select></div>`,`<div class="f179-field"><label>Payment Method</label><select id="payMethod">${['Bank Transfer','Cash','USDT','Card','Other'].map(x=>`<option>${x}</option>`).join('')}</select></div>`,fld('Payment Reference','payRef'),`<div class="f179-field"><label>Payment Proof</label><input id="payFile" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"></div>`]),`<button class="f179-btn" onclick="pspF179CloseModal()">Cancel</button><button class="f179-btn green" onclick="pspF179SaveSalaryPay('${id}')">Mark Paid</button>`)};
window.pspF179SaveSalaryPay=async id=>{const c=db(),r=byId(F.data.salary,id),s=byId(F.data.staff,r.staff_id);try{const file=q('#payFile').files[0],path=file?await upload(file,'salaries'):null,tx={transaction_type:'salary',direction:'debit',category:'Staff Salaries',subcategory:s?.full_name||'Staff',description:`Salary ${monthLabel(String(r.period_month).slice(0,7))} — ${s?.full_name||''}`,amount:n(r.payable_amount),currency:s?.currency||'USD',account_id:q('#payAccount').value||null,payment_method:q('#payMethod').value,status:'paid',transaction_date:new Date().toISOString().slice(0,10),period_month:r.period_month,paid_at:new Date().toISOString(),receipt_path:path,source:'salary',source_ref:'SALARY:'+r.id,created_by:curAdminId(),metadata:{approval_override:'true'}};let ins=await c.from('finance_transactions').upsert(tx,{onConflict:'source_ref'}).select().single();if(ins.error)throw ins.error;let u=await c.from('finance_salary_runs').update({status:'paid',paid_at:new Date().toISOString(),payment_method:q('#payMethod').value,payment_reference:q('#payRef').value.trim()||null,receipt_path:path,transaction_id:ins.data.id,updated_at:new Date().toISOString()}).eq('id',id);if(u.error)throw u.error;await audit('salary_paid',`Paid salary — ${s?.full_name||''}`,'finance_salary_run',id,r,{status:'paid'});pspF179CloseModal();await load()}catch(e){toast(e.message||String(e),'error')}};

window.pspF179OpenPartner=function(id){const p=id?byId(F.data.partners,id):{};modal(id?'Edit Partner':'Add Partner','Revenue-share rule for partner / instructor.',simpleForm([fld('Partner Name','fpName','text',p.partner_name||''),`<div class="f179-field"><label>Share Basis</label><select id="fpBasis"><option value="course_revenue" ${p.share_basis==='course_revenue'?'selected':''}>Course Revenue</option><option value="net_profit" ${p.share_basis==='net_profit'?'selected':''}>Pre-Payout Net Profit</option><option value="income_category" ${p.share_basis==='income_category'?'selected':''}>Specific Income Category</option></select></div>`,fld('Share %','fpShare','number',p.share_percent||0,'step="0.01" min="0" max="100"'),fld('Income Category (if specific)','fpCat','text',p.income_category||''),`<div class="f179-field full"><label>Payout Details</label><textarea id="fpDetails" rows="2">${esc(p.payout_details||'')}</textarea></div>`]),`<button class="f179-btn" onclick="pspF179CloseModal()">Cancel</button><button class="f179-btn primary" onclick="pspF179SavePartner('${id||''}')">Save Partner</button>`)};
window.pspF179SavePartner=async id=>{const c=db(),payload={partner_name:q('#fpName').value.trim(),share_basis:q('#fpBasis').value,share_percent:n(q('#fpShare').value),income_category:q('#fpCat').value.trim()||null,payout_details:q('#fpDetails').value.trim()||null,active:true,created_by:curAdminId(),updated_at:new Date().toISOString()};if(!payload.partner_name)return toast('Partner name required.','error');const r=id?await c.from('finance_partners').update(payload).eq('id',id):await c.from('finance_partners').insert(payload);if(r.error)return toast(r.error.message,'error');await audit(id?'partner_update':'partner_create','Saved partner share rule','finance_partner',id||null,null,payload);pspF179CloseModal();await load()};
window.pspF179SyncPartners=async()=>{const c=db(),r=await c.rpc('psp_finance_sync_partner_payouts',{p_month:monthStart()});if(r.error)return toast(r.error.message,'error');await load();toast('Partner payouts synced.')};
window.pspF179PayPartner=function(id){const r=byId(F.data.payouts,id),p=byId(F.data.partners,r.partner_id),bal=Math.max(0,n(r.amount_due)-n(r.amount_paid));modal('Record Partner Payment',`${esc(p?.partner_name||'Partner')} · outstanding ${money(bal)}`,simpleForm([fld('Amount To Pay','ppAmount','number',bal,'step="0.01" min="0.01"'),`<div class="f179-field"><label>Paid From</label><select id="ppAccount">${accountOptions()}</select></div>`,`<div class="f179-field"><label>Payment Method</label><select id="ppMethod">${['Bank Transfer','Cash','USDT','Card','Other'].map(x=>`<option>${x}</option>`).join('')}</select></div>`,fld('Reference','ppRef'),`<div class="f179-field"><label>Payment Proof</label><input id="ppFile" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"></div>`]),`<button class="f179-btn" onclick="pspF179CloseModal()">Cancel</button><button class="f179-btn green" onclick="pspF179SavePartnerPay('${id}')">Record Payment</button>`)};
window.pspF179SavePartnerPay=async id=>{const c=db(),r=byId(F.data.payouts,id),p=byId(F.data.partners,r.partner_id);try{const amt=n(q('#ppAmount').value),bal=Math.max(0,n(r.amount_due)-n(r.amount_paid));if(amt<=0||amt>bal+.01)throw new Error('Enter a valid amount up to the outstanding balance.');const file=q('#ppFile').files[0],path=file?await upload(file,'partners'):r.receipt_path||null,source='PARTNER:'+r.id+':'+Date.now(),tx={transaction_type:'partner_payout',direction:'debit',category:'Partner Payouts',subcategory:p?.partner_name||'Partner',description:`Partner payout — ${p?.partner_name||''}`,amount:amt,currency:'USD',account_id:q('#ppAccount').value||null,payment_method:q('#ppMethod').value,status:'paid',transaction_date:new Date().toISOString().slice(0,10),period_month:r.period_month,paid_at:new Date().toISOString(),receipt_path:path,source:'partner',source_ref:source,created_by:curAdminId(),metadata:{approval_override:'true'}};const ins=await c.from('finance_transactions').insert(tx).select().single();if(ins.error)throw ins.error;const paid=n(r.amount_paid)+amt,u=await c.from('finance_partner_payouts').update({amount_paid:paid,status:paid+0.005>=n(r.amount_due)?'paid':'partial',payment_method:q('#ppMethod').value,payment_reference:q('#ppRef').value.trim()||null,receipt_path:path,transaction_id:ins.data.id,updated_at:new Date().toISOString()}).eq('id',id);if(u.error)throw u.error;await audit('partner_payout_paid',`Paid partner — ${p?.partner_name||''}`,'finance_partner_payout',id,r,{amount_paid:paid});pspF179CloseModal();await load()}catch(e){toast(e.message||String(e),'error')}};

window.pspF179OpenAccount=function(){modal('Add Company Account','Bank, cash, payment gateway or wallet.',simpleForm([fld('Account Name','faName'),`<div class="f179-field"><label>Account Type</label><select id="faType">${['bank','cash','gateway','wallet','other'].map(x=>`<option>${x}</option>`).join('')}</select></div>`,`<div class="f179-field"><label>Currency</label><select id="faCurrency">${['USD','PKR','MYR','USDT'].map(x=>`<option>${x}</option>`).join('')}</select></div>`,fld('Opening Balance','faOpening','number',0,'step="0.01"'),`<div class="f179-field full"><label>Details</label><textarea id="faDetails" rows="2"></textarea></div>`]),`<button class="f179-btn" onclick="pspF179CloseModal()">Cancel</button><button class="f179-btn primary" onclick="pspF179SaveAccount()">Add Account</button>`)};
window.pspF179SaveAccount=async()=>{const c=db(),payload={name:q('#faName').value.trim(),account_type:q('#faType').value,currency:q('#faCurrency').value,opening_balance:n(q('#faOpening').value),details:q('#faDetails').value.trim()||null,active:true,created_by:curAdminId()};if(!payload.name)return toast('Account name required.','error');const r=await c.from('finance_accounts').insert(payload);if(r.error)return toast(r.error.message,'error');await audit('account_create','Created finance account','finance_account',null,null,payload);pspF179CloseModal();await load()};
window.pspF179SaveSettings=async()=>{const c=db(),amount=n(q('#f179ApprovalThreshold').value),payload={setting_key:'approval_threshold',setting_value:{amount,currency:'USD'},updated_by:curAdminId(),updated_at:new Date().toISOString()},r=await c.from('finance_settings').upsert(payload);if(r.error)return toast(r.error.message,'error');await load();toast('Finance setting saved.')};

window.pspF179OpenObligation=function(){modal('Add Payable / Receivable','Track money company owes or expects to receive.',simpleForm([`<div class="f179-field"><label>Type</label><select id="foType"><option value="payable">Payable</option><option value="receivable">Receivable</option></select></div>`,fld('Title','foTitle'),fld('Counterparty','foParty'),fld('Amount','foAmount','number','','step="0.01" min="0.01"'),fld('Due Date','foDue','date'),`<div class="f179-field"><label>Account</label><select id="foAccount">${accountOptions()}</select></div>`,`<div class="f179-field full"><label>Notes</label><textarea id="foNotes" rows="2"></textarea></div>`]),`<button class="f179-btn" onclick="pspF179CloseModal()">Cancel</button><button class="f179-btn primary" onclick="pspF179SaveObligation()">Save</button>`)};
window.pspF179SaveObligation=async()=>{const c=db(),payload={obligation_type:q('#foType').value,title:q('#foTitle').value.trim(),counterparty:q('#foParty').value.trim()||null,amount:n(q('#foAmount').value),currency:'USD',due_date:q('#foDue').value||null,status:'pending',account_id:q('#foAccount').value||null,notes:q('#foNotes').value.trim()||null,created_by:curAdminId()};if(!payload.title||!payload.amount)return toast('Title and amount required.','error');const r=await c.from('finance_obligations').insert(payload);if(r.error)return toast(r.error.message,'error');pspF179CloseModal();await load()};
window.pspF179SettleObligation=async id=>{const c=db(),o=byId(F.data.obligations,id),credit=o.obligation_type==='receivable',tx={transaction_type:o.obligation_type,direction:credit?'credit':'debit',category:credit?'Receivables Collected':'Payables Paid',description:o.title,amount:n(o.amount),currency:o.currency||'USD',account_id:o.account_id,status:'paid',transaction_date:new Date().toISOString().slice(0,10),paid_at:new Date().toISOString(),source:'manual',source_ref:'OBLIGATION:'+o.id,created_by:curAdminId(),metadata:{approval_override:'true'}};const ins=await c.from('finance_transactions').upsert(tx,{onConflict:'source_ref'}).select().single();if(ins.error)return toast(ins.error.message,'error');const u=await c.from('finance_obligations').update({status:credit?'received':'paid',transaction_id:ins.data.id,updated_at:new Date().toISOString()}).eq('id',id);if(u.error)return toast(u.error.message,'error');await load()};
window.pspF179OpenRecurring=function(){modal('Add Recurring Item','Automatically generated each month.',simpleForm([`<div class="f179-field"><label>Type</label><select id="frType"><option value="expense">Expense</option><option value="income">Income</option></select></div>`,fld('Title','frTitle'),fld('Category','frCategory'),fld('Amount','frAmount','number','','step="0.01" min="0.01"'),fld('Due Day','frDue','number',1,'min="1" max="28"'),`<div class="f179-field"><label>Account</label><select id="frAccount">${accountOptions()}</select></div>`]),`<button class="f179-btn" onclick="pspF179CloseModal()">Cancel</button><button class="f179-btn primary" onclick="pspF179SaveRecurring()">Save Recurring</button>`)};
window.pspF179SaveRecurring=async()=>{const c=db(),payload={item_type:q('#frType').value,title:q('#frTitle').value.trim(),category:q('#frCategory').value.trim(),amount:n(q('#frAmount').value),currency:'USD',due_day:n(q('#frDue').value)||1,account_id:q('#frAccount').value||null,active:true,created_by:curAdminId()};if(!payload.title||!payload.category||!payload.amount)return toast('Title, category and amount required.','error');const r=await c.from('finance_recurring_items').insert(payload);if(r.error)return toast(r.error.message,'error');await c.rpc('psp_finance_generate_recurring',{p_month:monthStart()});pspF179CloseModal();await load()};
window.pspF179OpenBudget=function(){modal('Set Monthly Budget',esc(monthLabel()),simpleForm([fld('Expense Category','fbCategory'),fld('Budget Amount','fbAmount','number','','step="0.01" min="0.01"'),fld('Warning at %','fbWarn','number',80,'min="1" max="100"')]),`<button class="f179-btn" onclick="pspF179CloseModal()">Cancel</button><button class="f179-btn primary" onclick="pspF179SaveBudget()">Save Budget</button>`)};
window.pspF179SaveBudget=async()=>{const c=db(),payload={period_month:monthStart(),category:q('#fbCategory').value.trim(),budget_amount:n(q('#fbAmount').value),warning_percent:n(q('#fbWarn').value)||80,created_by:curAdminId(),updated_at:new Date().toISOString()};if(!payload.category||!payload.budget_amount)return toast('Category and budget amount required.','error');const r=await c.from('finance_budgets').upsert(payload,{onConflict:'period_month,category'});if(r.error)return toast(r.error.message,'error');pspF179CloseModal();await load()};

window.pspF179CloseMonth=async()=>{if(closed())return;if(!await confirmX(`Close ${monthLabel()}? Existing transactions will be locked; later corrections must be Adjustment entries.`))return;const c=db(),r=await c.rpc('psp_finance_close_month',{p_month:monthStart()});if(r.error)return toast(r.error.message,'error');await audit('finance_month_close',`Closed finance month ${monthLabel()}`,'finance_month',F.month);await load();toast('Month closed and snapshot saved.')};
window.pspF179Month=async v=>{F.month=v||currentMonth();F._preparedMonth='';F._lastRenderKey='';localStorage.setItem('psp_finance_month_v179',F.month);await load({force:true})};
window.pspF179Tab=function(t){F.tab=t;localStorage.setItem('psp_finance_tab_v179',t);render()};
window.pspF179Filter=function(k,v){F.filters[k]=v;localStorage.setItem('psp_finance_filters_v179',JSON.stringify(F.filters));render()};

window.pspF179ExportExcel=function(){const tx=F.data.tx.filter(r=>String(r.period_month||'').slice(0,7)===F.month),s=summary();const rows=[['PipSePaisa Finance Report',monthLabel()],['Total Income',s.income],['Operating Expenses',s.op],['Staff Salaries',s.salaries],['Partner Payouts',s.partners],['Net Profit',s.net],['Profit Margin',s.margin+'%'],[],['Txn ID','Date','Type','Direction','Category','Description','Amount','Status','Source']].concat(tx.map(r=>[r.txn_code,r.transaction_date,r.transaction_type,r.direction,r.category,r.description||'',r.amount,r.status,r.source]));const html='<table>'+rows.map(r=>'<tr>'+r.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</table>';const blob=new Blob(['\ufeff'+html],{type:'application/vnd.ms-excel'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`PipSePaisa-Finance-${F.month}.xls`;a.click();URL.revokeObjectURL(a.href);audit('finance_export','Exported Excel finance report','finance_report',F.month)};
window.pspF179ExportPdf=function(){const s=summary(),w=window.open('','_blank');if(!w)return toast('Allow pop-ups to export PDF.','error');const tx=txForMonth().map(r=>`<tr><td>${esc(r.txn_code)}</td><td>${esc(r.transaction_date)}</td><td>${esc(r.category)}</td><td>${esc(r.description||'')}</td><td>${r.direction==='credit'?'+':'-'}${money(r.amount)}</td><td>${esc(r.status)}</td></tr>`).join('');w.document.write(`<!doctype html><html><head><title>PipSePaisa Finance ${esc(monthLabel())}</title><style>body{font:12px Arial;padding:28px;color:#172033}h1{margin:0}.sub{color:#6b7280;margin:4px 0 20px}.k{display:grid;grid-template-columns:repeat(6,1fr);gap:7px}.b{border:1px solid #ddd;padding:9px;border-radius:8px}.b small{display:block;color:#777}.b strong{font-size:16px}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{padding:7px;border-bottom:1px solid #ddd;text-align:left}th{background:#0b1724;color:#fff}</style></head><body><h1>PipSePaisa — Finance & Accounts</h1><div class="sub">${esc(monthLabel())} · Generated ${esc(new Date().toLocaleString())}</div><div class="k"><div class="b"><small>Income</small><strong>${money(s.income)}</strong></div><div class="b"><small>Operating</small><strong>${money(s.op)}</strong></div><div class="b"><small>Salaries</small><strong>${money(s.salaries)}</strong></div><div class="b"><small>Partner</small><strong>${money(s.partners)}</strong></div><div class="b"><small>Net Profit</small><strong>${money(s.net)}</strong></div><div class="b"><small>Margin</small><strong>${s.margin.toFixed(2)}%</strong></div></div><table><thead><tr><th>ID</th><th>Date</th><th>Category</th><th>Description</th><th>Amount</th><th>Status</th></tr></thead><tbody>${tx}</tbody></table><script>onload=()=>print()<\/script></body></html>`);w.document.close();audit('finance_export','Exported PDF finance report','finance_report',F.month)};

function wrapShow(){if(typeof window.showPage!=='function'||window.showPage.__v182finance)return;const old=window.showPage;function w(page,el){const out=old.apply(this,arguments);if(page==='revenue')setTimeout(()=>{syncTopbar();if(!q('#f179Root'))mount();if(F._loaded&&Date.now()-F._lastLoadAt<5000)render(false);else load()},40);return out}w.__v179finance=true;w.__v182finance=true;window.showPage=w}
async function init(){try{F.tab=localStorage.getItem('psp_finance_tab_v179')||'dashboard';F.month=localStorage.getItem('psp_finance_month_v179')||currentMonth();F.filters=Object.assign(F.filters,JSON.parse(localStorage.getItem('psp_finance_filters_v179')||'{}'))}catch(_){}mount();F._mounted=true;wrapShow();if(q('#page-revenue.page.active'))await load();setTimeout(wrapShow,800);setInterval(wrapShow,12000)}
window.pspFinance179Load=load;
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
